/// Exact schema-2 qualification workflow for the local feature fixture.
pub(super) const QUALIFICATION: &str = include_str!("snapshots/qualification-schema2-fixture.yml");

pub(super) fn marked(body: &str) -> String {
    let body = body.replace("@COMPILED_RELEASE_VERSION@", env!("CARGO_PKG_VERSION"));
    format!(
        "# Generated by Velnor Actions {}; edit .velnor/config.toml and regenerate.\n{body}",
        env!("CARGO_PKG_VERSION")
    )
}
